session_start();require_once 'includes/cek_session.php';require_once 'config/koneksi.php';$embed=(($_POST['embed']??'')==='1');function backT($e){header('Location: tindakan.php'.($e?'?embed=1':''));exit;}if($_SERVER['REQUEST_METHOD']!=='POST')backT($embed);$id=(int)($_POST['id']??0);$t=trim($_POST['tindakan']??'');$s=trim($_POST['status']??'');$valid=['Belum ditindaklanjuti','Dalam proses','Selesai'];if(!$id||$t===''||!in_array($s,$valid,true)){$_SESSION['pesan']='Isi tindakan dan pilih status yang valid.';backT($embed);}if(hak_role_efektif()===HAK_WALI_KELAS){
